/// <summary>
/// MET extensions MPJ_27582 for the <c>SalesInvoiceJournalPost</c> class.
/// </summary>
[ExtensionOf(classStr(SalesInvoiceJournalPost))]
internal final  class METSalesInvoiceJournalPost_Extension
{
    #ISOCountryRegionCodes
    private METDiscountClaimHelper discountClaimHelper;
    
}

Method.Source:
    /// <summary>
    /// Chain of Command; after posting, update metCustInvoiceJour record.
    /// </summary>
    protected void endPost()
    {
        METCustInvoiceJour metCustInvoiceJour;
        SalesTable         metSalesTableStd;
        METSalesTable      metSalesTable;

        next endPost();

        select firstonly CustInvoiceJour from metCustInvoiceJour
            where metCustInvoiceJour.CustInvoiceJour == custInvoiceJour.RecId;

        if(metCustInvoiceJour.CustInvoiceJour)
        {
            metCustInvoiceJour.updateIntegrationStatus(METIntegrationStatus::ReadyToSend);
        }

        select firstonly RecId from metSalesTable
            join metSalesTableStd
                where metSalesTableStd.SalesId == custInvoiceJour.SalesId
                   && metSalesTable.SalesTable == metSalesTableStd.RecId;

        if(metSalesTable.RecId)
        {
            metSalesTable.updateIntegrationStatus(METIntegrationStatus::ReadyToSend);
        }
    }

