    private AmountCur METGetDiscountAmountPosted(METSalesLinePriceComponentDetail _priceComponentDetail)
    {
        // POC get the total discount value instead of discount per unit from METSalesLinePriceComponentDetail
        // TODO will have to consider the tax
        /*SalesQty qtyOrdered = salesLine.SalesQty;
        SalesQty invoicedNowQty = updateNow;
        SalesQty alreadyInvoicedQty = qtyOrdered - (salesLine.RemainSalesPhysical + invoicedNowQty); // this quantity is being invoiced in current call, but has not been committed in DB.
        AmountCur periodicDiscountAmount = salesTable.InclTax == NoYes::yes ? salesPurchLine.salesPurchLineInterface().amountExclTax(_discountLine.Amount, invoicedNowQty, this.transDate, tax)
                                                                                : _discountLine.Amount;

        if (invoicedNowQty + alreadyInvoicedQty != qtyOrdered) // Still some qty is pending invoice.
        {
            periodicDiscountAmount = (periodicDiscountAmount / qtyOrdered) *  invoicedNowQty;
        }
        else // No more qty for this sales lines left for invoice.
        {
            periodicDiscountAmount = periodicDiscountAmount - (periodicDiscountAmount / qtyOrdered) * alreadyInvoicedQty;
        }*/
        
        AmountCur periodicDiscountAmount = _priceComponentDetail.VendorValue;

        return CurrencyExchangeHelper::amount(periodicDiscountAmount, salesPurchLine.salesPurchLineInterface().parmCurrencyCode());
    }

    /// <summary>
    /// posts after line
    /// </summary>
    protected void afterLinePost()
    {
        next afterLinePost();

        // If revenue recognition schedule is set for sales line, skip trade agreement sales revenue posting.
        if (/*FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&*/ !this.isProforma())
        {
            if (salesLine.RevRecRevenueScheduleID)
            {
                info("@GlobalUnifiedPricing:UseStandardSalesLineAmountPostingWithRevRecRevenueScheduleIDSet");
            }
            else
            {
                this.METPostSalesTradeAgreement();
                this.METPostMarginComponentAdjustments();
            }
        }
    }

    /// <summary>
    /// This method is for additional postings upon enabling of control
    /// </summary>
    private void metPostAdditionalCOGS()
    {
        METSalesLinePriceComponent  metSalesLinePriceComponent;
        METComponentCode            metComponentCode;
        LedgerVoucher               ledgerVoucherLocal  = this.getLedgerVoucher();
        LedgerVoucherObject         ledgerVoucherObject = ledgerVoucherLocal.findLedgerVoucherObject();
        CurrencyExchangeHelper      exchangeRateHelper  = CurrencyExchangeHelper::newExchangeDate(
                                                                                Ledger::primaryLedger(
                                                                                CompanyInfo::findDataArea(curext()).RecId),
                                                                                ledgerVoucherObject.parmAccountingDate());
        exchangeRateHelper.parmExchangeRate1(this.fixedExchRate());
        exchangeRateHelper.parmExchangeRate2(this.fixedExchRateSecondary());

        SalesLine salesLineDefaultDim;

        while select InventTransId, CurrencyCode, DefaultDimension from salesLineDefaultDim
                where salesLineDefaultDim.SalesId == salesTable.salesId
            join Value, Component, InventTransId from metSalesLinePriceComponent
                where metSalesLinePriceComponent.InventTransId == salesLineDefaultDim.InventTransId
            join MainAccountId from metComponentCode
                where metComponentCode.Component == metSalesLinePriceComponent.Component
                && metComponentCode.AdditionalPostingsToCOGS == NoYes::Yes
                && metComponentCode.MainAccountId != ''
        {
            RecId ledgerDimensionId = LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountId(metComponentCode.MainAccountId);

            if (ledgerDimensionId)
            {
                LedgerDimensionAccount ledgerDimensionMerged = this.getLedgerDimensionLineAmount();
                ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionMerged, salesLineDefaultDim.DefaultDimension);
                Amount value = metSalesLinePriceComponent.Value;
                        
                // For promotion and deals, we will have component detail lines, the amount used for claiming will be the sum of vendor value
                if (METSalesLinePriceComponentDetail::existComponent(salesLineDefaultDim.InventTransId, metSalesLinePriceComponent.Component))
                {
                    value = metSalesLinePriceComponent.getTotalVendorValue();
                }

                Amount postingAmount = CurrencyExchange::round(updateNow * value, salesLineDefaultDim.CurrencyCode);

                LedgerVoucherTransObject ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
                    ledgerVoucherObject,
                    LedgerPostingType::SalesConsump,
                    ledgerDimensionMerged,
                    salesLineDefaultDim.CurrencyCode,
                    postingAmount,
                    exchangeRateHelper);

                ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);

                ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionId, salesLine.DefaultDimension);
                ledgerDimensionMerged = LedgerDimensionFacade::serviceCreateLedgerDimension(ledgerDimensionMerged, salesLineDefaultDim.DefaultDimension);

                ledgerVoucherTransObject = LedgerVoucherTransObject::newTransactionAmountDefault(
                    ledgerVoucherObject,
                    LedgerPostingType::SalesRevenue,
                    ledgerDimensionMerged,
                    salesLineDefaultDim.CurrencyCode,
                    -1 * postingAmount,
                    exchangeRateHelper);

                ledgerVoucherLocal.addTrans(ledgerVoucherTransObject);
            }
        }
    }

    private void METPostMarginComponentAdjustments()
    {
        METSalesLinePriceComponent METSalesLinePriceComponent;
        METComponentCode    METComponentCode;
        /*if (!gupParameters.PostMarginComponentAdjustments)
        {
        return;
        }

        GUPPriceComponentCodeSetup priceComponentCodeSetup;
        GUPMarginComponentAdjustmentHistory adjustmentHistory;
        GUPPriceComponentCodePostingProfile priceComponentCodePostingProfile;*/

